def min_path_sum(grid):
    def f(r, c):               # cheapest path from (0, 0) to (r, c)
        if r < 0 or c < 0:
            return inf
        if r == 0 and c == 0:
            return grid[0][0]
        return grid[r][c] + min(f(r - 1, c), f(r, c - 1))
    return f(len(grid) - 1, len(grid[0]) - 1)

