def min_path_sum(grid):
    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]
    for r in range(m):
        for c in range(n):
            if r == 0 and c == 0:
                dp[r][c] = grid[0][0]
                continue
            up = dp[r - 1][c] if r else inf
            left = dp[r][c - 1] if c else inf
            dp[r][c] = grid[r][c] + min(up, left)
    return dp[m - 1][n - 1]

def min_path_sum(grid):
    n = len(grid[0])
    row = [inf] * n
    row[0] = 0
    for cells in grid:
        row[0] += cells[0]
        for c in range(1, n):
            row[c] = cells[c] + min(row[c], row[c - 1])
    return row[-1]

def min_path_sum(grid):
